"use client";
import * as React from "react";
import { cn } from "@/lib/utils";
import {
  Table,
  TableContainer,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
  type TableContainerProps,
} from "@/components/ui/table";
import {
  Pagination,
  type PaginationProps,
} from "@/components/ui/pagination";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { useFlowGroup } from "@/lib/cojeev-motion/use-flow";
export type DataTableColumn<T> = {
  id: string;
  header: React.ReactNode;
  accessorKey?: keyof T;
  cell?: (row: T) => React.ReactNode;
  numeric?: boolean;
  sortValue?: (row: T) => string | number;
  className?: string;
};
export type DataTableFilter<T> = {
  id: string;
  label: React.ReactNode;
  predicate: (row: T) => boolean;
};
export type DataTableProps<T> = Omit<
  React.ComponentProps<"div">,
  "children"
> & {
  data: T[];
  columns: DataTableColumn<T>[];
  /** The index is the row's position in data, before filtering or sorting. */
  getRowId?: (row: T, index: number) => string;
  filters?: DataTableFilter<T>[];
  filter?: string;
  defaultFilter?: string;
  onFilterChange?: (filter: string) => void;
  page?: number;
  defaultPage?: number;
  onPageChange?: (page: number) => void;
  pageSize?: number;
  emptyMessage?: React.ReactNode;
  caption?: string;
  onRowClick?: (row: T) => void;
  appearance?: "ledger" | "rich";
};
export function DataTable<T>({
  data,
  columns,
  getRowId,
  filters = [],
  filter,
  defaultFilter = "all",
  onFilterChange,
  page,
  defaultPage = 1,
  onPageChange,
  pageSize = 10,
  emptyMessage = "No matching records",
  caption,
  onRowClick,
  appearance,
  className,
  ...props
}: DataTableProps<T>) {
  const [localFilter, setLocalFilter] = React.useState(defaultFilter);
  const [localPage, setLocalPage] = React.useState(defaultPage);
  const [sort, setSort] = React.useState<{
    id: string;
    direction: "asc" | "desc";
  } | null>(null);
  const activeFilter = filter ?? localFilter;
  const selectedFilter = filters.find((f) => f.id === activeFilter);
  // Membership must retain a row's identity across filters, sorting and pages.
  // Consumers that insert/reorder source data should supply getRowId.
  const rows = React.useMemo(
    () =>
      data.map((row, sourceIndex) => ({
        row,
        id: getRowId?.(row, sourceIndex) ?? sourceIndex,
      })),
    [data, getRowId],
  );
  const filtered = React.useMemo(
    () =>
      selectedFilter
        ? rows.filter(({ row }) => selectedFilter.predicate(row))
        : rows,
    [rows, selectedFilter],
  );
  const sorted = React.useMemo(() => {
    const col = columns.find((c) => c.id === sort?.id);
    if (!sort || !col?.sortValue) return filtered;
    const value = col.sortValue;
    return [...filtered].sort((a, b) => {
      const av = value(a.row),
        bv = value(b.row);
      const delta =
        typeof av === "number" && typeof bv === "number"
          ? av - bv
          : String(av).localeCompare(String(bv));
      return sort.direction === "asc" ? delta : -delta;
    });
  }, [filtered, columns, sort]);
  const size = Math.max(
    1,
    Math.floor(Number.isFinite(pageSize) ? pageSize : 10),
  );
  const totalPages = Math.max(1, Math.ceil(sorted.length / size));
  const current = Math.max(
    1,
    Math.min(
      totalPages,
      Math.floor(Number.isFinite(page ?? localPage) ? (page ?? localPage) : 1),
    ),
  );
  const visible = sorted.slice((current - 1) * size, current * size);
  const setPage = (next: number) => {
    if (page === undefined) setLocalPage(next);
    onPageChange?.(next);
  };
  const setFilter = (next: string) => {
    if (filter === undefined) setLocalFilter(next);
    onFilterChange?.(next);
    setPage(1);
  };
  return (
    <div
      data-slot="data-table"
      data-appearance={appearance}
      data-state={filtered.length ? "full" : "filtered-empty"}
      className={cn("grid gap-[16px]", className)}
      {...props}
    >
      {filters.length > 0 && (
        <DataTableFilters aria-label="Filter records">
          <DataTableFilterButton
            pressed={activeFilter === "all"}
            onClick={() => setFilter("all")}
          >
            All <span>{data.length}</span>
          </DataTableFilterButton>
          {filters.map((f) => (
            <DataTableFilterButton
              key={f.id}
              pressed={activeFilter === f.id}
              onClick={() => setFilter(f.id)}
            >
              {f.label} <span>{data.filter(f.predicate).length}</span>
            </DataTableFilterButton>
          ))}
        </DataTableFilters>
      )}
      <DataTableViewport>
        <Table appearance={appearance}>
          {caption && <caption className="v-sr">{caption}</caption>}
          <TableHeader>
            <TableRow>
              {columns.map((col) => (
                <TableHead
                  key={col.id}
                  numeric={col.numeric}
                  className={col.className}
                  aria-sort={
                    sort?.id === col.id
                      ? sort.direction === "asc"
                        ? "ascending"
                        : "descending"
                      : col.sortValue
                        ? "none"
                        : undefined
                  }
                >
                  {col.sortValue ? (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      data-stable-hit=""
                      className="v-data-table__sort"
                      aria-label={`Sort ${typeof col.header === "string" ? col.header : col.id} ${sort?.id === col.id && sort.direction === "asc" ? "descending" : "ascending"}`}
                      onClick={() =>
                        setSort((old) => ({
                          id: col.id,
                          direction:
                            old?.id === col.id && old.direction === "asc"
                              ? "desc"
                              : "asc",
                        }))
                      }
                    >
                      {col.header}
                      <Icon
                        name={
                          sort?.id === col.id
                            ? sort.direction === "asc"
                              ? "chevron-up"
                              : "chevron-down"
                            : "arrow-up-down"
                        }
                        size="sm"
                      />
                    </Button>
                  ) : (
                    col.header
                  )}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {visible.map(({ row, id }) => (
              <TableRow
                key={id}
                data-row-id={id}
                tabIndex={onRowClick ? 0 : undefined}
                onClick={(event) => {
                  if (event.defaultPrevented) return;
                  const target = event.target as Element;
                  if (
                    target.closest(
                      "button,a,input,select,textarea,summary,[role='button'],[role='link'],[role='checkbox'],[role='switch'],[role='radio'],[contenteditable='true'],[data-row-action]",
                    )
                  )
                    return;
                  onRowClick?.(row);
                }}
                onKeyDown={(event) => {
                  if (
                    onRowClick &&
                    !event.defaultPrevented &&
                    event.target === event.currentTarget &&
                    (event.key === "Enter" || event.key === " ")
                  ) {
                    event.preventDefault();
                    onRowClick(row);
                  }
                }}
              >
                {columns.map((col) => (
                  <TableCell
                    key={col.id}
                    numeric={col.numeric}
                    className={col.className}
                  >
                    {col.cell
                      ? col.cell(row)
                      : col.accessorKey === undefined
                        ? null
                        : String(row[col.accessorKey] ?? "")}
                  </TableCell>
                ))}
              </TableRow>
            ))}
            {!filtered.length && (
              <TableRow>
                <TableCell colSpan={columns.length}>
                  <DataTableEmpty>
                    <b className="v-state__word">{emptyMessage}</b>
                    <span className="v-state__why">
                      {data.length
                        ? "Try another filter to see more records."
                        : "Add a record to begin this collection."}
                    </span>
                    {activeFilter !== "all" && (
                      <Button
                        variant="secondary"
                        size="sm"
                        onClick={() => setFilter("all")}
                      >
                        Clear filters
                      </Button>
                    )}
                  </DataTableEmpty>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </DataTableViewport>
      <div className="flex items-center justify-between gap-[12px] flex-wrap">
        <span className="v-meta" role="status">
          {filtered.length
            ? `${(current - 1) * size + 1}–${Math.min(current * size, filtered.length)} of ${filtered.length}`
            : "0"}{" "}
          records{activeFilter !== "all" && ` · ${data.length} total`}
        </span>
        {totalPages > 1 && (
          <DataTablePagination
            page={current}
            totalPages={totalPages}
            onPageChange={setPage}
          />
        )}
      </div>
    </div>
  );
}
export type DataTableViewportProps = TableContainerProps;
export function DataTableViewport(props: DataTableViewportProps) {
  return <TableContainer data-part="viewport" {...props} />;
}
export type DataTableFiltersProps = React.ComponentProps<"div">;
export function DataTableFilters({
  ref,
  className,
  ...props
}: DataTableFiltersProps) {
  const flowRef = useFlowGroup<HTMLDivElement>(ref);
  return (
    <div
      ref={flowRef}
      data-slot="data-table-filters"
      data-part="filters"
      data-filters=""
      role="group"
      className={cn("v-tabs -pills flex gap-[var(--s-2)]", className)}
      {...props}
    />
  );
}
export type DataTableFilterButtonProps = React.ComponentProps<typeof Button> & {
  pressed?: boolean;
};
export function DataTableFilterButton({
  className,
  pressed,
  ...props
}: DataTableFilterButtonProps) {
  return (
    <Button
      data-slot="data-table-filter-button"
      variant={pressed ? "accent" : "ghost"}
      size="sm"
      data-stable-hit=""
      className={cn("v-tab shrink-0", className)}
      type="button"
      aria-pressed={pressed}
      data-state={pressed ? "on" : "off"}
      {...props}
    />
  );
}
export type DataTablePaginationProps = PaginationProps;
export function DataTablePagination(props: DataTablePaginationProps) {
  return <Pagination data-part="pagination" {...props} />;
}
export type DataTableEmptyProps = React.ComponentProps<"div">;
export function DataTableEmpty({ className, ...props }: DataTableEmptyProps) {
  return (
    <div
      data-slot="data-table-empty"
      data-part="empty"
      className={cn(
        "v-state -filtered grid content-center justify-items-start gap-[var(--s-3)] p-[var(--s-6)] rounded-[var(--r-card)] bg-transparent border border-dashed border-[var(--v-border)] min-h-[160px]",
        className,
      )}
      role="status"
      {...props}
    />
  );
}

@layer cojeev-states {
[data-slot="data-table-filter-button"] {
  box-shadow: inset 0 0 0 1px var(--v-edge);
  min-height: 44px;
  gap: 8px;
}
[data-slot="data-table-filter-button"] > span:not(.v-btn__content) {
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
[data-slot="data-table-filters"] {
  flex-wrap: wrap;
  overflow: visible;
  padding: 4px;
}
[data-slot="data-table"] .v-data-table__sort {
  min-height: 44px;
  padding: 8px 6px;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  color: var(--v-text-2);
  gap: 8px;
}
[data-slot="data-table"]
  th[aria-sort]:not([aria-sort="none"])
  .v-data-table__sort {
  color: var(--v-accent-ink);
}
[data-slot="data-table-empty"] {
  white-space: normal;
  border: 0;
}
[data-slot="data-table"] [data-slot="pagination"] {
  font-size: 13px;
  padding-block: 4px;
}
[data-slot="data-table"] [data-slot="pagination"][data-composed] {
  max-width: 360px;
}
[data-slot="data-table-filters"]:not(.v-glide)
  [data-slot="data-table-filter-button"][aria-pressed="true"] {
  background: var(--v-ink);
  color: var(--v-on-ink);
}
:root[data-mode="dark"] [data-slot="data-table-filters"] [data-glide-active] {
  color: var(--v-on-accent);
}

[data-slot="data-table-empty"] .v-state__word {
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 8px;
}
[data-slot="data-table-empty"] .v-state__why {
  color: var(--muted-foreground);
  font-size: var(--fs-control);
  max-width: 44ch;
}
:root[data-mode="dark"] [data-slot="data-table-empty"] .v-state__why {
  color: var(--v-text-2);
}

}
